mapper.select:
SELECT FROM hotplaces h LEFT JOIN users u ON u.user_id = h.user_id LEFT JOIN historical_places p ON p.place_id = h.linked_place_id
AND ( h.title LIKE CONCAT('%', #{keyword}, '%') OR h.content LIKE CONCAT('%', #{keyword}, '%') OR h.address LIKE CONCAT('%', #{keyword}, '%') )
AND h.status = #{status}
ORDER BY h.hotplace_id DESC LIMIT #{limit} OFFSET #{offset}
